   <tbody>${st.filter(s=>s.st==='done').map(s=>`<tr ${CK('stop',r.n+'-'+s.i)}>${td(s.i,1)}${td('<b>'+esc(s.n)+'</b>')}${td(s.acc+' уп',1)}${td(fmt(s.acc*380),1)}${td(s.paid?fmt(s.paid):'—',1,'color:'+(s.paid?'var(--ok)':'var(--muted2)'))}${td(s.debt?fmt(s.debt):'—',1,'color:'+(s.debt?'var(--bad)':'var(--muted2)'))}</tr>`).join('')}</tbody>
