/* ====== ИНФРАСТРУКТУРА · с карточками вглубь ====== */
let D=[];
const allowed=k=>ROLES[role].s.indexOf(k)>=0;
/* какие карточки доступны роли */
const DT_ROLE={'Бригадир цеха':['shift','product','tech','raw','batch','worker','doc'],'Кладовщик':['product','batch','raw','supplier','doc','route','stop','order','shop','worker'],'Агент':['shop','order','debt','product','agent','route','stop'],'Экспедитор':['route','stop','order','shop','doc','cashin','product','debt','worker'],'Кассир':['cashin','route','stop','shop','debt','order','worker','agent'],'Бухгалтер':['worker','shift','product','tech','raw','supplier','doc','batch','cashin','route','shop','agent','order','stop','debt']};
const dtAllowed=k=>role==='Руководитель'||(DT_ROLE[role]||[]).indexOf(k)>=0;
function dt(k,id){if(!DT[k])return;if(!dtAllowed(k)){toast('Эту карточку роль «'+role+'» не видит — так работают права.');return}
 const top=D[D.length-1];if(top&&top.k===k&&String(top.id)===String(id))return;
 D.push({k,id});if(D.length>6)D.shift();render();const c=document.querySelector('.content');if(c)c.scrollTop=0}
function back(n){if(n===undefined)D.pop();else D=D.slice(0,n);render();const c=document.querySelector('.content');if(c)c.scrollTop=0}
function crumb(){return `<div class="crumb"><span class="back" onclick="back()">← Назад</span><a onclick="back(0)">${esc(SUBN[cur]||'Сводка')}</a>${D.map((d,i)=>`<i>›</i>${i===D.length-1?`<b>${esc(dtTitle(d.k,d.id))}</b>`:`<a onclick="back(${i+1})">${esc(dtTitle(d.k,d.id))}</a>`}`).join('')}<span class="mini" style="margin-left:auto">уровень ${D.length}</span></div>`}
function renderRoles(){const r=document.getElementById('roles');if(!r)return;
 r.innerHTML=Object.entries(ROLES).map(([k,v])=>`<div class="role" onclick="enter('${esc(k)}')"><div class="rav">${esc(v.av)}</div><div><b>${esc(k)}</b><span>${esc(v.n)} · ${esc(v.note)}</span></div></div>`).join('');
 const s=document.getElementById('rsel');if(s)s.innerHTML=Object.keys(ROLES).map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('');}
function enter(k){role=ROLES[k]?k:'Руководитель';document.getElementById('gate').classList.add('hidden');document.getElementById('app').classList.remove('hidden');
 const s=document.getElementById('rsel');if(s)s.value=role;document.getElementById('me').textContent=ROLES[role].av;if(!allowed(cur))cur=ROLES[role].s[0];D=[];build();
 toast(`Вы вошли как «${role}» · ${ROLES[role].n}. Показаны только разделы этой роли. Каждая строка открывается вглубь — попробуйте.`);}
function switchRole(k){role=k;document.getElementById('me').textContent=ROLES[role].av;const s=document.getElementById('rsel');if(s)s.value=role;if(!allowed(cur))cur=ROLES[role].s[0];D=D.filter(d=>dtAllowed(d.k));build();toast(`Роль: ${role}. Разделов доступно: ${ROLES[role].s.length}. ${ROLES[role].note}.`)}
const ownerOf=k=>SECOF[k];
function buildRail(){const on=ownerOf(cur);document.getElementById('rail').innerHTML=SEC.filter(s=>s.sub.some(x=>allowed(x[0]))).map(s=>{const n=s.sub.filter(x=>allowed(x[0])).length;return `<div class="ri ${s.k===on?'on':''}" onclick="go('${s.sub.filter(x=>allowed(x[0]))[0][0]}')" title="${esc(s.n)}"><i>${s.ic}</i><span>${esc(s.n)}</span>${n>1?`<b class="cnt">${n}</b>`:''}</div>`}).join('');}
function buildSub(){const on=ownerOf(cur),s=SEC.find(x=>x.k===on);if(!s)return;document.getElementById('sub').innerHTML=`<h4>${esc(s.n)}</h4>`+s.sub.filter(x=>allowed(x[0])).map(x=>`<a class="${x[0]===cur&&!D.length?'on':''}" onclick="go('${x[0]}')">${esc(x[1])}</a>`).join('')+`<div class="shint"><b>${esc(role)}</b><br>${esc(ROLES[role].note)}</div>`;}
function build(){buildRail();buildSub();render()}
function render(){let html;if(D.length){const d=D[D.length-1];try{html=crumb()+DT[d.k](d.id)}catch(e){D=[];html=(SC[cur]||SC.dash)()}}else html=(SC[cur]||SC.dash)();
 document.getElementById('ttl').textContent=(SUBN[cur]||'Сводка')+(D.length?' · '+DTN[D[D.length-1].k]:'');document.getElementById('content').innerHTML=`<div class="screen">${html}</div>`;const a=document.getElementById('addBtn');if(a)a.style.display=allowed('close')?'':'none';try{history.replaceState(null,'','?s='+cur+(D.length?'&d='+D[D.length-1].k+':'+encodeURIComponent(D[D.length-1].id):''))}catch(e){}}
function go(k){if(!allowed(k)){toast('Этой роли раздел недоступен — так работают права. Переключите роль в правом верхнем углу.');return}cur=k;D=[];build();const c=document.querySelector('.content');if(c)c.scrollTop=0}
function openM(t,s,b){document.getElementById('mt').innerHTML=t;document.getElementById('ms').innerHTML=s;document.getElementById('mbody').innerHTML=b;document.getElementById('mbg').classList.add('show');}
function closeM(){document.getElementById('mbg').classList.remove('show')}
let tt=null;function toast(m){const t=document.getElementById('toast');t.innerHTML=m;t.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>t.classList.remove('show'),6400)}
function applyTheme(){document.body.classList.toggle('dark',theme==='dark')}
function toggleTheme(){theme=theme==='dark'?'light':'dark';applyTheme();toast(theme==='dark'?'Тёмная тема.':'Светлая тема.')}

/* ====== СЦЕНАРИЙ ПОКАЗА ====== */
